package com.muxigame.city;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.item.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public final class CityTestsSupply {
    static int serial;
    static final String FOOD="city_settlements:cooked_rice", RAW="city_settlements:rice";
    static class Fixture implements AutoCloseable {
        final net.minecraft.server.MinecraftServer server;final net.minecraft.server.level.ServerLevel l;final CityEconomy e;final CityData data;final CityData.City c;final CitySimulation.Policy sim=new CitySimulation.Policy();final CityLogistics.Policy freight=new CityLogistics.Policy();final String business;final UUID food=UUID.randomUUID(),orphan=UUID.randomUUID(),overflow=UUID.randomUUID(),building=UUID.randomUUID();final List<UUID> people=new ArrayList<>();final BlockPos pos;
        Fixture(GameTestHelper h){l=h.getLevel();server=l.getServer();e=CityEconomy.get(server);data=CityData.get(server);pos=new BlockPos(19000000+(serial++)*32,-60,19000000);c=data.create(UUID.randomUUID(),"供应测试",l.dimension().location().toString(),CityBounds.between(pos,pos.offset(8,3,8)));business="business:"+c.id;e.adjust(business,10000,0,"test");e.state.simulation.put(c.id,sim);sim.enabled=true;freight.enabled=true;freight.visual=false;freight.items.add(FOOD);freight.supply.enabled=true;freight.supply.essentials.add(FOOD);freight.supply.overflowWarehouses.add(overflow);freight.supply.stockCaps.put(RAW,256);e.state.logistics.put(c.id,freight);
            for(var id:List.of(food,orphan,overflow)){c.warehouses.put(id,new CityRegistry.Warehouse(id,"仓",pos));e.state.warehouseOwners.put(id,business);sim.stocks.put(id,new CitySimulation.Stock());}
            c.buildings.put(building,new CityRegistry.Building(building,"厨房","工坊",c.bounds));var f=new CitySimulation.Facility();f.valid=true;f.stamp=CitySimulation.stamp(c,c.buildings.get(building));f.blocks.put("minecraft:smoker",8);sim.facilities.put(building,f);
            for(int i=0;i<8;i++){UUID id=UUID.randomUUID();people.add(id);c.residents.add(id);var r=new CitySimulation.Person();r.present=true;r.pos=pos.asLong();sim.people.put(id,r);e.adjust(CityEconomy.person(id),30,0,"test");var life=CityLiving.defaults(c.id,id);life.enabled=true;life.periodTicks=2400;life.basket.clear();var n=new CityLiving.Need();n.item=FOOD;n.essential=true;life.basket.add(n);e.state.living.put(id,life);}
            freight.merchants.add(people.getFirst());var shop=new CitySupply.Shop();shop.id=UUID.randomUUID();shop.warehouse=food;shop.item=FOOD;shop.buyPrice=1;freight.supply.shops.add(shop);e.invalidateIndexes();
        }
        void stock(UUID id,String item,int count){sim.stocks.get(id).goods.put(item,count);sim.stocks.get(id).physical.put(item,count);}
        int count(UUID id,String item){return sim.stocks.get(id).goods.getOrDefault(item,0);}
        long money(){return e.balance(business)+people.stream().mapToLong(id->e.balance(CityEconomy.person(id))).sum();}
        CitySupply.Kitchen kitchen(){var k=new CitySupply.Kitchen();k.building=building;k.warehouse=food;k.employer=business;k.inputs.put(RAW,4);k.outputs.put(FOOD,4);k.requiredBlocks.put("minecraft:smoker",1);k.wage=1;return k;}
        public void close(){e.state.production.removeIf(j->j.city.equals(c.id));e.state.merchants.removeIf(o->o.city.equals(c.id));for(var id:people){e.state.living.remove(id);e.state.accounts.remove(CityEconomy.person(id));}e.state.accounts.remove(business);e.state.simulation.remove(c.id);e.state.logistics.remove(c.id);for(var id:c.warehouses.keySet())e.state.warehouseOwners.remove(id);data.cities.remove(c.id);e.invalidateIndexes();data.setDirty();}
    }
    @GameTest(template="empty") public static void merchantSuccessionAndLegacy(GameTestHelper h){try(var f=new Fixture(h)){long money=f.money();CitySupply.shops(f.e,f.l,f.c,f.freight,0);var first=f.e.state.merchants.stream().filter(o->o.city.equals(f.c.id)).findFirst().orElseThrow();var oid=first.id;UUID previous=first.npc;CitySimulation.retire(f.e,f.data,f.c,f.sim,previous);CitySupply.shops(f.e,f.l,f.c,f.freight,200);var next=f.e.state.merchants.stream().filter(o->o.id.equals(oid)).findFirst().orElseThrow();h.assertTrue(!next.npc.equals(previous)&&next.buyPrice==1&&f.freight.enabled&&f.money()==money,"Successor preserves shop, price and money after actual retirement");CitySupply.shops(f.e,f.l,f.c,f.freight,400);h.assertTrue(f.e.state.merchants.stream().filter(o->o.id.equals(oid)).count()==1,"Repeated maintenance cannot duplicate shops");CityEconomy.validate(f.e.state);CityEconomy.references(f.e.state,f.data);var old=new CityLogistics.Policy();h.assertTrue(!old.supply.enabled,"Old data stays opt-out");}h.succeed();}
    @GameTest(template="empty") public static void emergencyStockAndRawOverflow(GameTestHelper h){try(var f=new Fixture(h)){f.stock(f.orphan,FOOD,128);CitySupply.shops(f.e,f.l,f.c,f.freight,0);long money=f.money();CityLogistics.cycle(f.server,f.e,f.c,f.freight,200);h.assertTrue(f.count(f.food,FOOD)==16&&f.count(f.orphan,FOOD)==112,"Emergency releases orphan stock below former 128 reserve");f.stock(f.food,RAW,1664);CityLogistics.cycle(f.server,f.e,f.c,f.freight,400);h.assertTrue(f.count(f.food,RAW)==1600&&f.count(f.overflow,RAW)==64&&f.money()==money,"Overflow transfers existing raw goods with finite storage and conserved funds");h.assertTrue(!f.l.hasChunkAt(f.pos),"Freight never loads city chunks");}h.succeed();}
    @GameTest(template="empty") public static void capsAndContractStandby(GameTestHelper h){try(var f=new Fixture(h)){var k=f.kitchen();var j=CitySupply.job(k,f.c.id,f.people.getFirst(),0);j.inputs.clear();j.outputs.clear();j.outputs.put(RAW,4);var box=new SimpleContainer(27);box.setItem(0,new ItemStack(CityMod.RICE.get(),64));f.freight.supply.stockCaps.put(RAW,64);long money=f.money();CityTestsSimulation.reject(h,()->CitySupply.prepare(f.e,f.l,f.c,j,box));h.assertTrue(box.getItem(0).getCount()==64&&f.money()==money,"Stock cap refuses output without mutation");f.freight.supply.standbyWagePercent=100;long balance=f.e.balance(f.business);h.assertTrue(CitySupply.prepare(f.e,f.l,f.c,j,box)==null&&box.getItem(0).getCount()==64&&f.e.balance(f.business)==balance-1&&f.money()==money,"Maintenance pay transfers actual employer money, no goods created");j.wage=3;f.freight.supply.standbyWagePercent=50;f.e.state.accounts.put(f.business,1L);h.assertTrue(CitySupply.prepare(f.e,f.l,f.c,j,box)==null&&f.e.balance(f.business)==0,"Partial maintenance contract charges only its configured affordable amount");f.e.state.accounts.put(f.business,0L);CityTestsSimulation.reject(h,()->CitySupply.prepare(f.e,f.l,f.c,j,box));h.assertTrue(box.getItem(0).getCount()==64,"Insolvent employer cannot issue money");}h.succeed();}
    @GameTest(template="empty") public static void staffedKitchenLongRun(GameTestHelper h){try(var f=new Fixture(h)){f.freight.supply.stockCaps.clear();f.freight.supply.standbyWagePercent=100;f.freight.supply.kitchens.add(f.kitchen());f.stock(f.food,RAW,1600);f.stock(f.food,FOOD,64);CitySupply.shops(f.e,f.l,f.c,f.freight,0);
            // Existing raw capacity and workers remain finite, and production requires real cached facilities.
            var farm=f.kitchen();farm.inputs.clear();farm.outputs.clear();farm.outputs.put(RAW,8);farm.wage=1;farm.requiredBlocks.clear();farm.requiredBlocks.put("city_settlements:rice_crop",8);f.sim.facilities.get(f.building).blocks.put("city_settlements:rice_crop",8);for(int i=3;i<7;i++)f.e.state.living.get(f.people.get(i)).guard=true;var farmer=CitySupply.job(farm,f.c.id,f.people.getLast(),0);farmer.resourceSource="rice";f.e.state.production.add(farmer);long money=f.money();
            for(int cycle=0;cycle<200;cycle++){long now=cycle*2400L;CitySupply.staff(f.e,f.l,f.c,f.freight.supply,now);for(var j:new ArrayList<>(f.e.state.production))if(j.enabled&&j.city.equals(f.c.id)){try{f.e.produce(f.server,j);}catch(IllegalArgumentException ignored){}}for(int i=3;i<7;i++)f.e.transfer(f.business,CityEconomy.person(f.people.get(i)),1,CityEconomy.Purpose.WAGE,"guard",now);for(var id:f.people)CityLiving.cycle(f.server,f.e,f.e.state.living.get(id),now);}
            h.assertTrue(f.freight.supply.reassignments==3,"Food capacity recruits only three workers, not one every cycle");h.assertTrue(f.e.state.production.stream().filter(j->j.enabled&&j.city.equals(f.c.id)).map(j->j.worker).distinct().count()==4,"One production job per worker");h.assertTrue(f.money()==money&&!f.l.hasChunkAt(f.pos),"200 background cycles conserve money without loading chunks");h.assertTrue(f.people.stream().allMatch(id->f.e.state.living.get(id).lastEssentials&&f.sim.people.get(id).hunger==0),"All residents remain fed after 200 cycles");h.assertTrue(f.count(f.food,RAW)+f.count(f.food,FOOD)==1664,"Only real conversion and production/consumption change stock");CityEconomy.validate(f.e.state);CityEconomy.references(f.e.state,f.data);
        }h.succeed();}
    @GameTest(template="empty") public static void reassignmentNeedsSurplusAndFacilities(GameTestHelper h){try(var f=new Fixture(h)){
        var kitchen=f.kitchen();kitchen.maxWorkers=16;f.freight.supply.kitchens.add(kitchen);f.sim.facilities.get(f.building).blocks.put("minecraft:stone",6);
        for(var id:f.people){var j=CitySupply.job(f.kitchen(),f.c.id,id,9000);j.inputs.clear();j.outputs.clear();j.outputs.put("minecraft:cobblestone",6);j.requiredBlocks.clear();j.requiredBlocks.put("minecraft:stone",6);j.resourceSource="quarry";f.e.state.production.add(j);}
        CitySupply.staff(f.e,f.l,f.c,f.freight.supply,0);h.assertTrue(f.freight.supply.reassignments==0,"Scarce donor stocks prevent reassignment");f.stock(f.overflow,"minecraft:cobblestone",1000);long money=f.money();CitySupply.staff(f.e,f.l,f.c,f.freight.supply,2400);
        h.assertTrue(f.freight.supply.reassignments==1&&f.e.state.production.stream().filter(j->j.city.equals(f.c.id)&&!j.enabled).count()==1&&f.money()==money,"Surplus worker changes one job; old mandate retained, no wage paid early");
        var added=f.e.state.production.stream().filter(j->j.city.equals(f.c.id)&&j.inputs.containsKey(RAW)).findFirst().orElseThrow();h.assertTrue(added.nextTick==9000,"Reassignment cannot bypass previous production cooldown");f.sim.facilities.get(f.building).valid=false;CitySupply.staff(f.e,f.l,f.c,f.freight.supply,4800);h.assertTrue(f.freight.supply.reassignments==1,"Damaged facility cannot recruit");CityEconomy.validate(f.e.state);CityEconomy.references(f.e.state,f.data);CityEconomy.decode(f.e.export());
    }h.succeed();}

}
